// EegApiDevice: the protocol of docs/control.md, "Over the network (UDP)". Do not edit this file
// (see EegApiDevice.h).

#include "EegApiDevice.h"
#include <stdarg.h>

#if defined(ARDUINO_ARCH_ESP32)
  // lwIP sockets: WiFiUDP cuts a received datagram at 1460 bytes. Even so, the ESP32 Arduino core
  // does not reassemble fragmented datagrams: a message longer than ~1470 bytes never arrives
  // (the engine's messages for the modes served over UDP are much shorter).
  #include "lwip/sockets.h"
  #include "esp_mac.h"
  static int sock = -1;
  static const size_t BUFFER_SIZE = 8192;
#else
  static WiFiUDP udp;
  static const size_t BUFFER_SIZE = 2048;
#endif

static const char *HELLO_WORD = "EEG_API_Unicorn";
static const uint32_t HELLO_MS = 1000;       // one hello per second while not connected
static const uint32_t ALIVE_MS = 1000;       // one "alive" per second once connected
static const uint32_t SILENCE_MS = 5000;     // no news from the engine: disconnected
static const uint32_t RESEND_MS = 2000;      // a command with no reply goes again (safe)
static char received[BUFFER_SIZE + 1];

// strlcpy does not exist on every board.
static void copy(char *to, const char *from, size_t size) { snprintf(to, size, "%s", from); }

// Serial.printf exists on the ESP32 only.
static void say(const char *format, ...) {
  char line[256];
  va_list args;
  va_start(args, format);
  vsnprintf(line, sizeof(line), format, args);
  va_end(args);
  Serial.println(line);
}

// --- the transport ------------------------------------------------------------------------------

// Can be called again (after the Wi-Fi came back): the lwIP socket survives a reconnection and is
// kept; the WiFiS3 one lives in the Wi-Fi module and is opened again.
bool EegApiDevice::openSocket() {
#if defined(ARDUINO_ARCH_ESP32)
  if (sock >= 0) return true;
  sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
  if (sock < 0) return false;
  int yes = 1;
  setsockopt(sock, SOL_SOCKET, SO_BROADCAST, &yes, sizeof(yes));
  sockaddr_in here = {};
  here.sin_family = AF_INET;
  here.sin_port = htons(settings.devicePort);
  here.sin_addr.s_addr = htonl(INADDR_ANY);
  if (bind(sock, (sockaddr *) &here, sizeof(here)) < 0) {
    closesocket(sock);
    sock = -1;
    return false;
  }
  return true;
#else
  udp.stop();
  return udp.begin(settings.devicePort) == 1;
#endif
}

void EegApiDevice::sendText(const char *text, size_t n, IPAddress ip, uint16_t port) {
#if defined(ARDUINO_ARCH_ESP32)
  sockaddr_in to = {};
  to.sin_family = AF_INET;
  to.sin_port = htons(port);
  to.sin_addr.s_addr = (uint32_t) ip;
  sendto(sock, text, n, 0, (const sockaddr *) &to, sizeof(to));
#else
  udp.beginPacket(ip, port);
  udp.write((const uint8_t *) text, n);
  udp.endPacket();
#endif
}

// One message = one JSON object = one datagram, always with "v": 1.
void EegApiDevice::sendJson(JsonDocument &doc, IPAddress ip, uint16_t port) {
  doc["v"] = 1;
  char text[512];
  size_t n = serializeJson(doc, text, sizeof(text));
  sendText(text, n, ip, port);
}

void EegApiDevice::readAll() {
  for (uint8_t k = 0; k < 32; k++) {     // everything waiting, without spending the day on it
#if defined(ARDUINO_ARCH_ESP32)
    sockaddr_in src;
    socklen_t addrLen = sizeof(src);
    // One byte more than the maximum: a datagram that is too big shows, and is ignored.
    int n = recvfrom(sock, received, sizeof(received), MSG_DONTWAIT, (sockaddr *) &src, &addrLen);
    if (n <= 0) return;
    if ((size_t) n > BUFFER_SIZE) continue;
    receive(received, n, IPAddress(src.sin_addr.s_addr), ntohs(src.sin_port));
#else
    int size = udp.parsePacket();
    if (size <= 0) return;
    IPAddress ip = udp.remoteIP();
    uint16_t port = udp.remotePort();
    if ((size_t) size > BUFFER_SIZE) {
      while (udp.available()) udp.read();
      continue;
    }
    int n = udp.read((uint8_t *) received, BUFFER_SIZE);
    if (n > 0) receive(received, n, ip, port);
#endif
  }
}

IPAddress EegApiDevice::broadcastAddress() {
  if (settings.engineIp && settings.engineIp[0]) {
    IPAddress ip;
    ip.fromString(settings.engineIp);
    return ip;
  }
#if defined(ARDUINO_ARCH_ESP32)
  return WiFi.broadcastIP();
#else
  IPAddress local = WiFi.localIP(), mask = WiFi.subnetMask(), out;
  for (int i = 0; i < 4; i++) out[i] = local[i] | (uint8_t) ~mask[i];
  return out;
#endif
}

// --- the protocol -------------------------------------------------------------------------------

bool EegApiDevice::begin(const EegApiSettings &s) {
  settings = s;
  if (settings.deviceId && settings.deviceId[0]) {
    copy(ident, settings.deviceId, sizeof(ident));
  } else {
    uint8_t mac[6];
#if defined(ARDUINO_ARCH_ESP32)
    // Read from the eFuses: WiFi.macAddress() returns zeros until the station has started.
    esp_read_mac(mac, ESP_MAC_WIFI_STA);
#else
    WiFi.macAddress(mac);
#endif
    snprintf(ident, sizeof(ident), "%02X:%02X", mac[4], mac[5]);
  }
  open = openSocket();
  if (!open) say("cannot open UDP port %u", settings.devicePort);
  helloMs = 0;
  return open;
}

void EegApiDevice::hello() {
  JsonDocument doc;
  doc["hello"] = HELLO_WORD;
  doc["app"] = settings.appName;
  doc["id"] = ident;
  doc["port"] = settings.devicePort;
  sendJson(doc, broadcastAddress(), settings.enginePort);
}

// Sends a command of docs/control.md and keeps it: with no reply within 2 s, it goes again as it
// is (same ref). The engine's four commands can safely arrive twice.
void EegApiDevice::sendCommand(JsonDocument &doc) {
  doc["v"] = 1;
  doc["mode"] = settings.mode;
  pendingRef = nextRef++;
  doc["ref"] = pendingRef;
  commandLength = serializeJson(doc, command, sizeof(command));
  say("-> engine: %s", command);
  sendText(command, commandLength, engineAddress, enginePortSeen);
  sentMs = millis();
}

void EegApiDevice::setParams() {
  JsonDocument doc;
  doc["cmd"] = "set_params";
  JsonDocument params;
  if (deserializeJson(params, settings.settingsJson) || !params.is<JsonObject>()) {
    refuse("settings", "the settings of config.h are not a JSON object");
    return;
  }
  if (params.as<JsonObject>().size() == 0) {   // nothing to set: start at once
    if (settingsCallback) settingsCallback();
    startMode();
    return;
  }
  doc["params"] = params;
  state = SETTING;
  sendCommand(doc);
}

void EegApiDevice::startMode() {
  JsonDocument doc;
  doc["cmd"] = "start_mode";
  state = STARTING;
  sendCommand(doc);
  startRef = pendingRef;
}

// The end of the connection, whatever the reason: we announce ourselves again.
void EegApiDevice::finish(const char *why) {
  say("%s: announcing ourselves again", why);
  state = ANNOUNCING;
  pendingRef = startRef = 0;
  helloMs = 0;
  currentPhase[0] = 0;
  if (disconnectedCallback) disconnectedCallback();
}

void EegApiDevice::refuse(const char *what, const char *reason) {
  say("%s refused: %s", what, reason);
  say("in the console, \"Disconnect\" then \"Connect\" tries again");
  state = REFUSED;
  pendingRef = 0;
  if (refusedCallback) refusedCallback(reason);
}

void EegApiDevice::connectRequest(JsonDocument &m, IPAddress ip, uint16_t port) {
  const char *host = m["host"] | "?";
  if (state != ANNOUNCING && !(ip == engineAddress && port == enginePortSeen)) {
    JsonDocument r;
    r["connected"] = false;
    r["busy"] = consoleHost;
    sendJson(r, ip, port);
    say("\"%s\" wants to connect us, but \"%s\" already has: answered busy", host, consoleHost);
    return;
  }
  // The same console connects us again: it had lost us. Everything starts over.
  if (state != ANNOUNCING && disconnectedCallback) disconnectedCallback();
  engineAddress = ip;
  enginePortSeen = port;
  copy(consoleHost, host, sizeof(consoleHost));
  lastSeq = 0;                           // a new connection: its seq starts again from 0
  heardMs = aliveMs = millis();
  currentPhase[0] = 0;
  startRef = 0;
  JsonDocument r;
  r["connected"] = true;
  sendJson(r, ip, port);
  say("connected by the console of \"%s\"", host);
  setParams();
}

void EegApiDevice::reply(JsonDocument &m) {
  if (pendingRef == 0 || !m["ref"].is<long>() || m["ref"].as<long>() != pendingRef) return;
  pendingRef = 0;                        // a duplicate reply (after a resend) is ignored
  if (!(m["accepted"] == true)) {
    refuse(state == SETTING ? "settings" : "start", m["reason"] | "?");
    return;
  }
  say("<- engine: %s accepted%s", m["cmd"] | "?",
      m["already_running"] == true ? " (the mode was already running)" : "");
  if (m["warning"].is<const char *>()) say("   engine's reservation: %s", m["warning"].as<const char *>());
  if (state == SETTING) {
    if (settingsCallback) settingsCallback();
    startMode();
  } else if (state == STARTING) {
    state = PLAYING;
    say(m["deferred"] == true
        ? "started: this mode needs a model, choose it in the console, then \"Start decoding\""
        : "started: look at no target during the warm-up and the rest");
  }
}

void EegApiDevice::receive(const char *text, size_t n, IPAddress ip, uint16_t port) {
  JsonDocument m;
  if (deserializeJson(m, text, n)) return;             // not JSON: ignored
  if (!m.is<JsonObject>() || !m["v"].is<int>() || m["v"].as<int>() != 1) return;
  if (m["identify"] == true) {
    if (state == ANNOUNCING && identifyCallback) identifyCallback();
    return;
  }
  if (!m["connect"].isNull()) {
    connectRequest(m, ip, port);
    return;
  }
  if (state == ANNOUNCING || !(ip == engineAddress && port == enginePortSeen)) return;
  heardMs = millis();                    // any message from the engine is a sign of life
  if (!m["alive"].isNull()) return;
  if (m["seq"].is<long>()) {
    long seq = m["seq"].as<long>();
    if (seq <= lastSeq) return;          // older than the last one: arrived late
    lastSeq = seq;
  }
  const char *event = m["event"] | "";
  if (!strcmp(event, "disconnected")) {
    finish(!strcmp(m["cause"] | "", "console") ? "disconnected in the console" : "the engine stopped");
  } else if (!strcmp(event, "failed")) {
    if (m["ref"].is<long>() && m["ref"].as<long>() == startRef) refuse("start", m["reason"] | "?");
  } else if (m["status"].is<JsonObject>()) {
    const char *phase = m["status"]["phase"] | "";
    if (strcmp(phase, currentPhase)) {
      copy(currentPhase, phase, sizeof(currentPhase));
      say("engine: phase %s", currentPhase);
      const char *instruction = m["status"]["instruction"] | "";
      if (instruction[0]) say("   %s", instruction);
      if (phaseCallback) phaseCallback(currentPhase);
    }
  } else if (m["decision"].is<JsonObject>()) {
    if (state == PLAYING && decisionCallback) decisionCallback(m["decision"].as<JsonObject>());
  } else if (!m["ref"].isNull()) {
    reply(m);
  }
}

void EegApiDevice::loop() {
  if (!open) return;
  uint32_t t = millis();
  if (WiFi.status() != WL_CONNECTED) {
    // Wi-Fi lost: 5 s without news, the connection is over.
    if (state != ANNOUNCING && t - heardMs >= SILENCE_MS) finish("5 s without news from the engine");
    return;
  }
  readAll();
  t = millis();
  if (state == ANNOUNCING) {
    if (helloMs == 0 || t - helloMs >= HELLO_MS) {
      helloMs = t;
      hello();
    }
    return;
  }
  if (t - aliveMs >= ALIVE_MS) {
    aliveMs = t;
    JsonDocument alive;
    alive["alive"] = true;
    sendJson(alive, engineAddress, enginePortSeen);
  }
  if (pendingRef != 0 && t - sentMs >= RESEND_MS) {
    say("no reply within 2 s: command or reply lost, sending again");
    sendText(command, commandLength, engineAddress, enginePortSeen);
    sentMs = t;
  }
  if (t - heardMs >= SILENCE_MS) finish("5 s without news from the engine");
}
